#include <stdio.h>
int adj[55][55], vis[55], V, E, st[55], top=-1;
void push(int v) { st[++top]=v; }
int pop() { return st[top--]; }
void dfs(int start) {
    push(start); int first=1;
    while(top>=0) {
        int u = pop();
        if(!vis[u]) {
            printf("%s%d", first?"":" ", u); first=0; vis[u]=1;
            for(int i=V-1; i>=0; i--) if(adj[u][i] && !vis[i]) push(i);
        }
    }
}
