}

#include <stdio.h>
int adj[55][55], vis[55], V, E;
int dfs(int u, int p) {
    vis[u]=1;
    for(int i=0; i<V; i++) {
        if(adj[u][i]) {
            if(!vis[i]) { if(dfs(i, u)) return 1; }
            else if(i!=p) return 1;
        }
    }
    return 0;
}
int main() {
    if(scanf("%d %d", &V, &E)!=2) return 0;
    for(int i=0, u, v; i<E; i++) { scanf("%d %d", &u, &v); adj[u][v]=1; adj[v][u]=1; }
    int cycle=0;
    for(int i=0; i<V; i++) if(!vis[i]) if(dfs(i, -1)) { cycle=1; break; }
    if(cycle) printf("Cycle exists\n"); else printf("No cycle\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct { int u, v, w; } Edge;
Edge e[1500]; int parent[55], V, E;
int find(int i) { while(parent[i]!=i) i=parent[i]; return i; }
void unionP(int i, int j) { int root_i=find(i), root_j=find(j); if(root_i != root_j) parent[root_i] = root_j; }
int cmp(const void* a, const void* b) { Edge* e1=(Edge*)a; Edge* e2=(Edge*)b; if(e1->w != e2->w) return e1->w - e2->w; if(e1->u != e2->u) return e1->u - e2->u; return e1->v - e2->v; }
int main() {
    if(scanf("%d %d", &V, &E)!=2) return 0;
    for(int i=0; i<E; i++) scanf("%d %d %d", &e[i].u, &e[i].v, &e[i].w);
    qsort(e, E, sizeof(Edge), cmp);
    for(int i=0; i<V; i++) parent[i]=i;
    int cost=0, edges=0;
    for(int i=0; i<E && edges<V-1; i++) {
        if(find(e[i].u) != find(e[i].v)) {
            cost += e[i].w; edges++;
            printf("%d-%d: %d\n", e[i].u, e[i].v, e[i].w);
            unionP(e[i].u, e[i].v);
        }
    }
    printf("Total Cost: %d\n", cost);
    return 0;
}

#include <stdio.h>
#define INF 999999
int adj[55][55], V, E, key[55], parent[55], mstSet[55];
int main() {
    if(scanf("%d %d", &V, &E)!=2) return 0;
    for(int i=0; i<V; i++) for(int j=0; j<V; j++) adj[i][j]=INF;
    for(int i=0, u, v, w; i<E; i++) { scanf("%d %d %d", &u, &v, &w); adj[u][v]=w; adj[v][u]=w; }
    for(int i=0; i<V; i++) { key[i]=INF; mstSet[i]=0; parent[i]=-1; }
    key[0]=0;
    for(int c=0; c<V-1; c++) {
        int min=INF, u=-1;
        for(int v=0; v<V; v++) if(!mstSet[v] && key[v]<min) { min=key[v]; u=v; }
        if(u==-1) break;
        mstSet[u]=1;
        for(int v=0; v<V; v++) if(adj[u][v]!=INF && !mstSet[v] && adj[u][v]<key[v]) { parent[v]=u; key[v]=adj[u][v]; }
    }
    int cost=0;
    for(int i=1; i<V; i++) {
        if(parent[i]!=-1) {
            int rU = parent[i]<i?parent[i]:i, rV=parent[i]>i?parent[i]:i;
            printf("%d-%d: %d\n", rU, rV, adj[parent[i]][i]);
            cost+=adj[parent[i]][i];
        }
    }
    printf("Total Cost: %d\n", cost);
    return 0;
}

#include <stdio.h>
#define INF 999999
int adj[55][55], dist[55], sptSet[55], V, E;
int main() {
    int src; if(scanf("%d %d", &V, &E)!=2) return 0;
    for(int i=0; i<V; i++) for(int j=0; j<V; j++) adj[i][j]=INF;
    for(int i=0, u, v, w; i<E; i++) { scanf("%d %d %d", &u, &v, &w); adj[u][v]=w; adj[v][u]=w; }
    if(scanf("%d", &src)!=1) return 0;
    for(int i=0; i<V; i++) { dist[i]=INF; sptSet[i]=0; }
    dist[src]=0;
    for(int count=0; count<V-1; count++) {
        int min=INF, u=-1;
        for(int v=0; v<V; v++) if(!sptSet[v] && dist[v]<=min) { min=dist[v]; u=v; }
        if(u==-1) break;
        sptSet[u]=1;
        for(int v=0; v<V; v++)
            if(!sptSet[v] && adj[u][v]!=INF && dist[u]!=INF && dist[u]+adj[u][v] < dist[v])
                dist[v] = dist[u] + adj[u][v];
    }
    for(int i=0; i<V; i++) {
        if(dist[i]==INF) printf("Vertex %d: INF\n", i);
        else printf("Vertex %d: %d\n", i, dist[i]);
    }
    return 0;
}
